INSERT INTO public.theme_versions(theme_id,version)
SELECT t.id,'2.0.0' FROM public.themes t JOIN public.theme_studio_presets p ON p.folder_name=t.folder_name
WHERE NOT EXISTS(SELECT 1 FROM public.theme_versions v WHERE v.theme_id=t.id AND v.version='2.0.0');
CREATE OR REPLACE FUNCTION public.provision_default_studio_theme(p_store uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v uuid; doc jsonb; target uuid; page record;
BEGIN
 PERFORM 1 FROM stores WHERE id=p_store FOR UPDATE;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM store_themes WHERE store_id=p_store AND is_active) THEN RETURN; END IF;
 SELECT tv.id,pr.document INTO v,doc FROM theme_versions tv JOIN themes t ON t.id=tv.theme_id JOIN theme_studio_presets pr ON pr.folder_name=t.folder_name WHERE t.folder_name='default' AND tv.version='2.0.0' AND NOT tv.is_deprecated;
 IF v IS NULL THEN RAISE EXCEPTION 'Default studio theme is not provisioned'; END IF;
 INSERT INTO store_themes(store_id,theme_version_id,is_active,global_tokens) VALUES(p_store,v,false,doc->'tokens') ON CONFLICT(store_id,theme_version_id) DO NOTHING;
 SELECT id INTO target FROM store_themes WHERE store_id=p_store AND theme_version_id=v;
 FOR page IN SELECT * FROM jsonb_each(doc->'pages') LOOP
  INSERT INTO store_theme_templates(store_theme_id,page_type,settings_data) VALUES(target,page.key,page.value) ON CONFLICT(store_theme_id,page_type) DO NOTHING;
 END LOOP;
 UPDATE store_themes SET is_active=true WHERE id=target;
END $$;
REVOKE ALL ON FUNCTION public.provision_default_studio_theme(uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.new_store_default_studio() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN PERFORM provision_default_studio_theme(NEW.id); RETURN NEW; END $$;
DROP TRIGGER IF EXISTS new_store_default_studio ON public.stores;
CREATE TRIGGER new_store_default_studio AFTER INSERT ON public.stores FOR EACH ROW EXECUTE FUNCTION public.new_store_default_studio();
SELECT public.provision_default_studio_theme(id) FROM public.stores WHERE NOT EXISTS(SELECT 1 FROM public.store_themes st WHERE st.store_id=stores.id AND st.is_active);
NOTIFY pgrst,'reload schema';
COMMIT;
